func novelJSONFileHash(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func novelLoadTableJSON(dbRows *sql.Rows) ([]json.RawMessage, error) {
	defer dbRows.Close()
	out := make([]json.RawMessage, 0)
	for dbRows.Next() {
		var data string
		if err := dbRows.Scan(&data); err != nil {
			return nil, err
		}
		out = append(out, json.RawMessage(data))
	}
	return out, dbRows.Err()
}

func novelMirrorPayloads(cmd *cobra.Command) (map[string][]byte, []novelMirrorFile, bool, error) {
	exists, err := novelLocalStoreExists(cmd)
	if err != nil {
		return nil, nil, false, err
	}
	if !exists {
		return map[string][]byte{}, []novelMirrorFile{}, true, nil
	}
	db, err := novelOpenStore(cmd)
	if err != nil {
		return nil, nil, false, err
	}
	defer db.Close()
	return novelMirrorSnapshot(cmd.Context(), db.DB())
}

func novelMirrorSnapshot(ctx context.Context, db *sql.DB) (map[string][]byte, []novelMirrorFile, bool, error) {
	tx, err := db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return nil, nil, false, err
	}
	defer tx.Rollback()
	tables := map[string]string{
		"documents.json":  `SELECT data FROM documents ORDER BY id`,
		"highlights.json": `SELECT data FROM highlights ORDER BY CAST(id AS TEXT)`,
		"books.json":      `SELECT data FROM books ORDER BY CAST(id AS TEXT)`,
		"tags.json":       `SELECT data FROM reader_tags UNION ALL SELECT data FROM book_tags UNION ALL SELECT data FROM highlight_tags ORDER BY 1`,
	}
	names := make([]string, 0, len(tables))
	for name := range tables {
		names = append(names, name)
	}
	sort.Strings(names)
	payloads := map[string][]byte{}
	files := make([]novelMirrorFile, 0, len(names))
	total := 0
	for _, name := range names {
		rows, err := tx.QueryContext(ctx, tables[name])
		if err != nil {
			return nil, nil, false, err
		}
		items, err := novelLoadTableJSON(rows)
		if err != nil {
			return nil, nil, false, err
		}
		total += len(items)
		data, err := json.MarshalIndent(items, "", "  ")
		if err != nil {
			return nil, nil, false, err
		}
		data = append(data, '\n')
		payloads[name] = data
		files = append(files, novelMirrorFile{Name: name, Count: len(items), SHA256: novelJSONFileHash(data)})
	}
	if err := tx.Commit(); err != nil {
		return nil, nil, false, err
	}
	return payloads, files, total == 0, nil
}

func novelReadManifest(path string) map[string]string {
	raw, err := os.ReadFile(path)
	if err != nil {
		return map[string]string{}
	}
	var manifest novelMirrorManifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		return map[string]string{}
	}
	out := map[string]string{}
	for _, f := range manifest.Files {
		out[f.Name] = f.SHA256
	}
	return out
}

func novelVerifyMirror(exportDir string, files []novelMirrorFile) ([]string, error) {
	mismatches := make([]string, 0)
	for _, f := range files {
		raw, err := os.ReadFile(filepath.Join(exportDir, f.Name))
		if err != nil {
			mismatches = append(mismatches, f.Name)
			continue
		}
		if novelJSONFileHash(raw) != f.SHA256 {
			mismatches = append(mismatches, f.Name)
		}
	}
	return mismatches, nil
}

func novelWritePrivateFile(path string, data []byte) error {
	f, err := os.CreateTemp(filepath.Dir(path), ".readwise-mirror-*")
	if err != nil {
		return err
	}
	tmp := f.Name()
	defer os.Remove(tmp)
	defer f.Close()
	if err := f.Chmod(0o600); err != nil {
		return err
	}
	if _, err := f.Write(data); err != nil {
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func novelExistingMirrorFiles(exportDir string, files []novelMirrorFile) []string {
	existing := make([]string, 0)
	for _, f := range files {
		name := filepath.Join(exportDir, f.Name)
		if info, err := os.Stat(name); err == nil && !info.IsDir() {
			existing = append(existing, f.Name)
		}
	}
	if info, err := os.Stat(filepath.Join(exportDir, "manifest.json")); err == nil && !info.IsDir() {
		existing = append(existing, "manifest.json")
	}
	sort.Strings(existing)
	return existing
}

